/// <summary>
/// Chain of Comand methode for isComplete
/// </summary>
/// <returns>
/// return true if all field filled otherwise false
/// </returns>
protected boolean isComplete()
{
    boolean                 avaIsComplete;
    WHSContainerTypeCode    avaContainerTypeCode;

    avaIsComplete        = next isComplete();
    avaContainerTypeCode = controller.parmSessionState().parmPass().avaParmContainerType();

    if (!avaContainerTypeCode)
    {
        avaIsComplete = false;
    }

    return avaIsComplete;
}
